installer-gui-script.script:
function stopWith(title, message) {
  my.result.type = 'Fatal';
  my.result.title = title;
  my.result.message = message;
  return false;
}
function checkUpdate() {
  // Every profile has its own VPN entry ("OFTC VPN", "OFTC VPN (<name>)", ...), all
  // naming the app's bundle id; the preinstall script runs the same test.
  var vpn = system.run('/bin/sh', '-c',
    '/usr/sbin/scutil --nc list 2>/dev/null | /usr/bin/grep "com[.]chris[.]openforticlient[.]oftc" | /usr/bin/grep -qE "[(](Connected|Connecting|Disconnecting|Reasserting)[)]" && exit 10; exit 0');
  if (vpn !== 0) {
    return stopWith('Disconnect OFTC before updating',
      'Disconnect every OFTC VPN from its controls or System Settings > VPN, then reopen this installer. Installer will ask to close the app. Your saved VPN settings will be kept.');
  }
  var app = system.run('/usr/bin/pgrep', '-f',
    '^/Applications/(OFTC|Open Forticlient)\\.app/Contents/MacOS/OFTCAgent([[:space:]]|$)');
  // A running idle app is handled by must-close at the installation
  // stage. Rejecting it here makes that native closing step unreachable.
  if (app !== 0 && app !== 1) {
    return stopWith('Could not check whether OFTC is running',
      'Disconnect and quit OFTC, then reopen this installer to try again.');
  }
  return true;
}
